from typing import List


class Solution:
    def stringSequence(self, target: str) -> List[str]:
        result = []
        current = ""
        for ch in target:
            if current and current[-1] == ch:
                current += ch
                result.append(current)
                continue
            for code in range(ord("a"), ord(ch) + 1):
                result.append(current + chr(code))
            current += ch
        return result

from typing import List


class Solution:
    def stringSequence(self, target: str) -> List[str]:
        if len(target) == 1:
            return [chr(code) for code in range(ord("a"), ord(target))]
        result = []
        current = ""
        for ch in target:
            for code in range(ord("a"), ord(ch) + 1):
                result.append(current + chr(code))
            current += ch
        return result
